/bin/bash -lc "python - <<'PY'
from babel.messages.pofile import read_po
for loc in ['ta']:
 with open(f'sphinx/locale/{loc}/LC_MESSAGES/sphinx.po',encoding='utf-8') as f:
  for m in read_po(f,locale=None,ignore_obsolete=False):
   if m.id and m.string and (not isinstance(m.string,tuple) or any(m.string)):
    print(loc, repr(m.id), '=>', repr(m.string), 'at', m.locations)
PY"

