/bin/bash -lc "python - <<'PY'
from babel.messages.pofile import read_po
with open('sphinx/locale/zh_CN/LC_MESSAGES/sphinx.po',encoding='utf-8') as f: body=[m for m in read_po(f,locale=None,ignore_obsolete=False) if m.id]
tr=[m for m in body if m.string and (not isinstance(m.string,tuple) or any(m.string))]
a={}
for m in tr:
 for fn,_ in m.locations:
  ps=fn.split('/'); k=ps[1] if len(ps)>1 else ps[0]; a[k]=a.get(k,0)+1
print(dict(sorted(a.items(),key=lambda x:(-x[1],x[0]))))
PY"

